use std::{fs,path::Path,collections::BTreeSet};use serde_json::{Value,json};use sha2::{Sha256,Digest};
const R:&str="/home/ubuntu/src/zopro-perf-work/group-input212";const SEED:&str="/home/ubuntu/src/zopro-perf-work/group-cpu211/proof-sha256-after-main.json";
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn hash(b:&[u8])->String{format!("{:x}",Sha256::digest(b))}
fn filehash(p:impl AsRef<Path>)->String{hash(&fs::read(p).unwrap())}
fn decimal(s:&str)->[u64;4]{let mut p=[0u64;4];for d in s.bytes(){let mut c=(d-b'0')as u128;for v in &mut p{c+=*v as u128*10;*v=c as u64;c>>=64;}assert_eq!(c,0);}p}
fn counts(b:&[u8])->Value{let p=decimal("21888242871839275222246405745257275088548364400416034343698204186575808495617");let mut values=BTreeSet::new();let(mut zero,mut one)=(0,0);for raw in b.chunks_exact(32){let words: [u64;4]=std::array::from_fn(|i|u64::from_le_bytes(raw[i*8..i*8+8].try_into().unwrap()));assert!(words.iter().rev().cmp(p.iter().rev()).is_lt());zero+=usize::from(words==[0;4]);one+=usize::from(words==[1,0,0,0]);values.insert(words);}json!({"words":b.len()/32,"zero":zero,"one":one,"distinct":values.len(),"distinct_nonzero":values.len()-usize::from(zero>0),"sha256":hash(b)})}
fn main(){let r=Path::new(R);for(p,h)in read(r.join("pins.json")).as_object().unwrap(){assert_eq!(filehash(p),h.as_str().unwrap());}assert_eq!(filehash(SEED),"25f3486018e2702859911f4e047fb105d57020648a30aa46d2579e6262ad6e2b");let mut ledger:BTreeSet<String>=serde_json::from_value(read(SEED)).unwrap();assert_eq!(ledger.len(),58980);let jobs=read(r.join("jobs.json"));let mut source=None;let mut arms=vec![];let mut receipts=0;let mut calls=0;
 for j in jobs.as_array().unwrap(){let arm=j["arm"].as_str().unwrap();let out=fs::read_to_string(r.join(format!("run/dump-{arm}/stdout.log"))).unwrap();assert!(out.contains("exited normally"));assert!(out.contains("INPUT_DUMPS 4\n"));assert_eq!(out.lines().filter(|l|l.starts_with("INPUT_DUMP hit=")).count(),4);let mut summaries=out.lines().filter_map(|l|l.strip_prefix("SUMMARY "));let summary:Value=serde_json::from_str(summaries.next().unwrap()).unwrap();assert!(summaries.next().is_none());assert_eq!(summary["rounds"],1);assert_eq!(summary["priming"],3);assert_eq!(summary["workers"],32);assert_eq!(summary["placement_before"],summary["placement_after"]);assert_eq!(summary["boolean_routes"],if j["boolean"]==true{json!([0,1,0,0])}else{json!([0,0,0,0])});
 let mut dumps=vec![];for hit in 1..=4{let p=r.join(format!("dumps/{arm}/scalar-{hit}.bin"));let bytes=fs::read(&p).unwrap();assert_eq!(bytes.len(),962848);let equal=source.as_ref().is_none_or(|s:&Vec<u8>|*s==bytes);if source.is_none(){source=Some(bytes.clone());}let line=out.lines().find(|l|l.starts_with(&format!("INPUT_DUMP hit={hit} "))).unwrap();dumps.push(json!({"hit":hit,"bytes":bytes.len(),"sha256":hash(&bytes),"equal_first":equal,"counts":counts(&bytes),"entry_record":line}));}
 for name in[format!("dump-{arm}"),format!("verify-{arm}")]{let d=r.join("run").join(name);let e=read(d.join("exit.json"));assert_eq!(e["returncode"],0);for s in["stdout","stderr"]{assert_eq!(filehash(d.join(format!("{s}.log"))),e[format!("{s}_sha256")]);}receipts+=1;}
 let pd=Path::new(j["proof_dir"].as_str().unwrap());assert_eq!(fs::metadata(pd.join("0.proof")).unwrap().len(),164);let proof=filehash(pd.join("0.proof"));assert!(ledger.insert(proof.clone()));assert_eq!(filehash(pd.join("0.public")),j["public_sha256"]);let verification=fs::read_to_string(r.join(format!("run/verify-{arm}/stdout.log"))).unwrap();assert!(verification.contains(&format!("VERIFIED proof_sha256={proof} ")));arms.push(json!({"arm":arm,"dumps":dumps,"proof_sha256":proof,"SDK_wall_time_ignored":true}));calls+=4;
 }
 let bytes=source.unwrap();let fixture=fs::read("/home/ubuntu/src/zopro-perf-work/g2-queue-scan175/inputs/1x2.b2q").unwrap();assert_eq!(hash(&fixture),"421d6ba37e8b3a6f5feb23829c174d11bc034cb9bd8874adf672d65038fb0ad0");assert_eq!(&fixture[..8],b"B2SCAN01");let n=u64::from_le_bytes(fixture[8..16].try_into().unwrap())as usize;assert_eq!(n,30089);let old=&fixture[16+128*n..];assert_eq!(old.len(),bytes.len());let fixture_comparison=json!({"postcapture_exploratory_crosscheck":true,"exact_equal":bytes==old,"different_words":bytes.chunks_exact(32).zip(old.chunks_exact(32)).filter(|(a,b)|a!=b).count(),"fixture_scalar_counts":counts(old),"actual_scalar_counts":counts(&bytes)});
 let equal=arms.iter().flat_map(|a|a["dumps"].as_array().unwrap()).all(|d|d["equal_first"]==true);let output=r.join("proof-sha256-after-audit.json");assert!(!output.exists());fs::write(&output,serde_json::to_vec_pretty(&ledger).unwrap()).unwrap();assert_eq!(ledger.len(),58982);let result=json!({"pass":true,"data_audit_only":true,"all8_inputs_exact_equal":equal,"arms":arms,"fixture_comparison":fixture_comparison,"fresh_Gnark_exports":2,"SDK_calls":calls,"receipts":receipts,"stream_hashes":receipts*2,"canonical_count":ledger.len(),"canonical_sha256":filehash(output),"sdk_unchanged":true,"no_performance_claim":true});fs::write(r.join("result.json"),serde_json::to_vec_pretty(&result).unwrap()).unwrap();println!("{result}");}
